@Service
public class ProjectService {
    @Autowired
    private ProjectRepository projectRepository;

    // Creates a new project – entire method is transactional
    @Transactional
    public ProjectDto createProject(CreateProjectRequestDto request) {
        // Sequence number generation is inside the transaction
        String ref = generateRef();
        Project project = new Project(ref, request.getTitle());
        project.setDescription(request.getDescription());
        project = projectRepository.save(project);
        return mapToDto(project);
